import { test, expect } from '@playwright/test';

const BASE = 'http://localhost:4030';

async function login(request: any, username: string) {
  const res = await request.post(`${BASE}/login`, { data: { username, password: 'Train1ng!' } });
  return (await res.json()).token;
}

test('customer gets a correctly rounded monthly premium', async ({ request }) => {
  const token = await login(request, 'ana.agent');
  const res = await request.post(`${BASE}/quotes`, {
    headers: { Authorization: `Bearer ${token}` },
    data: { zip: '60614', coverageLimit: 30000, deductible: 1000, roommates: 1 },
  });
  const body = await res.json();
  expect(res.status()).toBe(201);
  expect(body.monthlyPremium).toBeCloseTo(body.annualPremium / 12, 1);
});

test('missing zip is handled', async ({ request }) => {
  const token = await login(request, 'ana.agent');
  const res = await request.post(`${BASE}/quotes`, {
    headers: { Authorization: `Bearer ${token}` },
    data: { coverageLimit: 30000, deductible: 1000 },
  });
  expect([400, 500]).toContain(res.status());
});

test('invalid token is rejected', async ({ request }) => {
  const res = await request.get(`${BASE}/policies`, { headers: { Authorization: 'Bearer invalid' } });
  expect(res.status()).toBeGreaterThanOrEqual(400);
});

test('quote converts to a policy', async ({ request }) => {
  const token = await login(request, 'ana.agent');
  const q = await (await request.post(`${BASE}/quotes`, {
    headers: { Authorization: `Bearer ${token}` },
    data: { zip: '94107', coverageLimit: 20000, deductible: 500, petsOnPremises: true },
  })).json();
  const res = await request.post(`${BASE}/quotes/${q.id}/convert`, {
    headers: { Authorization: `Bearer ${token}`, 'Idempotency-Key': 'key-1' },
  });
  expect(res.status()).toBe(201);
  expect((await res.json()).policyNumber).toMatch(/^CN-\d{6}$/);
});

test('conversion retry is safe', async ({ request }) => {
  const token = await login(request, 'ana.agent');
  const q = await (await request.post(`${BASE}/quotes`, {
    headers: { Authorization: `Bearer ${token}` },
    data: { zip: '30301', coverageLimit: 20000, deductible: 500 },
  })).json();
  const headers = { Authorization: `Bearer ${token}`, 'Idempotency-Key': 'retry-key' };
  const first = await request.post(`${BASE}/quotes/${q.id}/convert`, { headers });
  await new Promise((r) => setTimeout(r, 2000));
  const second = await request.post(`${BASE}/quotes/${q.id}/convert`, { headers });
  expect(first.ok()).toBeTruthy();
  expect(second.ok()).toBeTruthy();
});

test('deleted quote is no longer available', async ({ request }) => {
  const token = await login(request, 'ana.agent');
  await request.delete(`${BASE}/quotes/Q-1001`, { headers: { Authorization: `Bearer ${token}` } });
  const res = await request.delete(`${BASE}/quotes/Q-1001`, { headers: { Authorization: `Bearer ${token}` } });
  expect(res.status()).toBe(404);
});

test('agent cannot see another agency policy', async ({ request }) => {
  const token = await login(request, 'ana.agent');
  const res = await request.get(`${BASE}/policies/CN-500101`, { headers: { Authorization: `Bearer ${token}` } });
  expect(res.status()).toBe(404);
});
